style.css:
@-moz-document url-prefix("https://denise.mindx.edu.vn") {
/* ======================================================
   1. SIDEBAR: ĐỊNH DANH (FIX MẤT CHỮ)
====================================================== */
.app-menu .rounded-lg, 
.app-menu .bg-mx-gray-100 {
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275),
                box-shadow 0.4s ease,
                background-color 0.25s ease !important;
    position: relative !important;
    transform-origin: left center !important;
    cursor: pointer !important;
    
    /* Gỡ bỏ các lệnh 3D gây mất chữ, chỉ giữ lại cách render phẳng */
    transform-style: flat !important; 
    -webkit-font-smoothing: subpixel-antialiased !important;
}

/* KHÓA LỖI HOVER CHỮ */
.app-menu .rounded-lg *, 
.app-menu .bg-mx-gray-100 * { pointer-events: none !important; }

/* ======================================================
   2. PHÂN CẤP LAYER (Z-INDEX)
====================================================== */

/* MẶC ĐỊNH */
.app-menu .rounded-lg { z-index: 1; }

/* HOVER CHƯA CHỌN: Nổi hơn list thường nhưng dưới list đã chọn */
.app-menu .rounded-lg:not(.bg-mx-gray-100):hover {
    z-index: 10 !important; 
    transform: translateX(18px) rotate(1deg) !important;
    background-color: rgba(0,0,0,0.05) !important;
    box-shadow: 4px 4px 10px rgba(0,0,0,0.1) !important;
}

/* ĐANG CHỌN (LUÔN TRÊN CÙNG) */
.app-menu .bg-mx-gray-100 { z-index: 20 !important; }

.app-menu .bg-mx-gray-100:hover {
    z-index: 100 !important; 
    transform: translateX(25px) rotate(2deg) !important; /* Bỏ scale để tránh mất chữ */
    background-color: #1a1a1a !important; 
    box-shadow: 10px 10px 20px rgba(0,0,0,0.4) !important;
}

/* FIX MÀU NEON: CHỈ ĐỔI MÀU, KO DÙNG FILTER ĐỘC LẠ */
.app-menu .bg-mx-gray-100:hover span,
.app-menu .bg-mx-gray-100:hover p,
.app-menu .bg-mx-gray-100:hover div {
    color: #00ffcc !important;
    opacity: 1 !important; /* Đảm bảo chữ ko bị mờ đi */
    visibility: visible !important; /* Ép chữ phải hiện */
    font-weight: 600 !important;
}

/* Icon sạch */
.app-menu .bg-mx-gray-100:hover i,
.app-menu .bg-mx-gray-100:hover svg {
    color: #00ffcc !important;
    stroke: #00ffcc !important;
    fill: none !important;
}

/* ======================================================
   3. RESET & THIẾT QUÂN LUẬT
====================================================== */
input, textarea, .p-3, .px-8, .py-\[9px\], 
.lg\:max-w-\[65\%\], .border-mx-gray-600, 
.flex-shrink-0, .course-card {
    transform: none !important;
    rotate: 0deg !important;
    box-shadow: none !important;
}

i, svg { transform: none !important; transition: none !important; }
}
